effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float px = detail / max(acScreenSize.y, 1.0);
  float l = gmLum(c);
  float lx = gmLum(texture2DCv(inputImg.texture, uv + vec2(px, 0.0)).rgb / max(texture2DCv(inputImg.texture, uv + vec2(px, 0.0)).a, 1e-4));
  float ly = gmLum(texture2DCv(inputImg.texture, uv + vec2(0.0, px)).rgb / max(texture2DCv(inputImg.texture, uv + vec2(0.0, px)).a, 1e-4));
  float g = length(vec2(l - lx, l - ly)) * 8.0 * contrast;
  float shade = clamp(paper - g, 0.0, 1.0);
  vec3 col = mix(vec3(gmLum(c) * 0.5 + 0.5), vec3(shade), 1.0);
  col = vec3(shade);
  col = mix(c, col, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
